export const getPhotosByCategory = (category) => {
  return qaratPhotos.filter(p => p.category.toLowerCase().includes(category.toLowerCase()));
};

export const getPhotosBySubfolder = (subfolder) => {
  return qaratPhotos.filter(p => p.subfolder === subfolder);
};

export const getPhotosByTargetPage = (pagePath) => {
  return qaratPhotos.filter(p => p.targetPage.includes(pagePath));
};

export default qaratPhotos;
